	PROFACAD_ADVISE_NEXT_FMT = "Conseil : prochains points dans %s (racine %d/%d) — le chapitre ci-dessous explique pourquoi.",
	PROFACAD_ADVISE_DONE = "Conseil : racines recommandées complètes — remplis les sous-nœuds ou les autres arbres.",
	PROFHUB_TAB_OVERVIEW = "Aperçu",
	PROFHUB_TAB_TREASURES = "Trésors & Livres",
	PROFHUB_TAB_COURSE = "Cours (101)",
	PROFHUB_OVERVIEW_HINT = "Trésors & Livres : trésors de PS uniques et livres avec points de repère. Cours (101) : le cours débutant — les chapitres s'affichent pour tes métiers. Liste hebdo de PS : bientôt.",
	INFO_DRAWER_BODY_PROFHUB = "Tout ce qui touche aux métiers au même endroit. Aperçu montre tes métiers, points de Savoir et conseils d'arbre en direct ; Trésors & Livres suit les trésors de PS uniques avec points de repère ; Cours (101) est le cours débutant.",
	PROFACAD_CH_KNOWLEDGE_TITLE = "C'est quoi, le Savoir ?",
	PROFACAD_CH_KNOWLEDGE_BODY = "Chaque métier d'artisanat et de récolte de Midnight a un arbre de spécialisation, et les points de Savoir (PS) servent à le remplir. Tu gagnes des PS via des sources uniques (premières fabrications, trésors cachés, livres de renommée) et des activités hebdomadaires — le système est conçu pour se construire sur des semaines, pas des jours.\n\nCuisine, Pêche et Archéologie n'ont pas d'arbres et n'ont pas besoin de PS.\n\nPas de stress si tu es \"en retard\" : il existe un système de rattrapage, et ce cours t'accompagne étape par étape.",
	PROFACAD_CH_KNOWLEDGE_TASK = "Ouvre ta fenêtre de métier (touche par défaut : K) et regarde l'onglet Spécialisations.",
	PROFACAD_CH_GEARUP_TITLE = "S'équiper : outils, stations & premières recettes",
	PROFACAD_CH_GEARUP_BODY = "Tout d'abord : le menu déroulant en haut de la fenêtre de métier change d'ère d'extension — tout ce cours concerne l'ère MIDNIGHT. Elle n'est pas dans la liste ? Apprends-la auprès des formateurs de Lune-d'argent.\n\nChaque métier a aussi son propre équipement — 1 outil et 2 accessoires — dans des emplacements dédiés en haut de la fenêtre de métier (K). Sans outil équipé, beaucoup de recettes ne se fabriquent tout simplement pas. La plupart des outils et accessoires sont fabriqués par D'AUTRES métiers (forge, travail du cuir) — achète-les à l'hôtel des ventes (catégorie Équipement de métier) ou demande à un artisan ; le vendeur de fournitures a parfois des versions de base. L'enchantement est particulier et fabrique ses propres baguettes : achète la baguette de base bon marché chez le vendeur, fabrique la version runique au lutrin d'enchanteur (recette de formateur dès le niveau 1) et équipe-la.\n\nBouton de fabrication grisé ? Lis la ligne d'exigence de la recette : elle indique s'il te manque un outil ou s'il faut être à une station (enclume, lutrin, feu de cuisine...). Les stations sont autour du quartier des formateurs à Lune-d'argent.\n\nApprends ensuite tes premières recettes chez le formateur et fabrique-les — la compétence 25 débloque tes arbres de spécialisation, et chaque première fabrication donne +1 PS.",
	PROFACAD_CH_GEARUP_TASK = "Équipe un outil pour chacun de tes métiers.",
	PROFACAD_CH_TREES_TITLE = "Choisir ses arbres — sans regret",
	PROFACAD_CH_TREES_BODY = "Les points de Savoir sont permanents : il n'existe actuellement aucun moyen de les rembourser ou de respec. Ça fait peur, mais avec un petit plan, tu ne peux pas vraiment te tromper.\n\nLes arbres se débloquent avec ta compétence (le premier vers 25, d'autres ensuite). Le schéma classique : choisis UN arbre qui correspond à ton objectif, remplis d'abord sa racine (souvent ~30 points), puis pousse une sous-branche (~20 points) avant de toucher aux autres arbres.\n\nDès que tu as des métiers, leurs chapitres de départ ci-dessous donnent une build concrète — et MH affiche ici des conseils en direct pour tes propres arbres.",
	PROFACAD_CH_TREES_TASK = "Regarde tes arbres et choisis UN premier objectif — ne dépense rien pour l'instant.",
	PROFACAD_CH_RECIPES_TITLE = "D'où viennent les recettes ?",
	PROFACAD_CH_RECIPES_BODY = "Les recettes viennent de cinq sources : ton formateur (à acheter en montant ta compétence), tes arbres de spécialisation (débloqués en dépensant des PS), les vendeurs Moxie (chapitre suivant), les récompenses de renommée et les butins ou trésors du monde.\n\nRègle d'or : fabrique chaque nouvelle recette au moins une fois. Chaque première fabrication donne +1 PS et 10x Moxie — même si tu revends le résultat au vendeur.\n\nUn guide mentionne une recette que tu n'as pas ? Vérifie d'abord d'où elle vient avant de farmer.",
	PROFACAD_CH_RECIPES_TASK = "Apprends une nouvelle recette et fabrique-la une fois (première fabrication = +1 PS + Moxie).",
	PROFACAD_CH_MOXIE_TITLE = "La Moxie, ton argent de poche",
	PROFACAD_CH_MOXIE_BODY = "L'Artisan's Moxie est une monnaie propre à chaque métier : ta Moxie d'Enchantement n'achète que des choses d'Enchantement. Tu gagnes environ 5x Moxie par PS, et 10x via les premières fabrications.\n\nDépense-la chez les vendeurs de métiers de Lune-d'argent : nouvelles recettes, sacs de matériaux et livres donnant des PS bonus.\n\nAstuce : ne thésaurise pas sans fin — les premières recettes et les livres de PS sont le meilleur investissement.",
	PROFACAD_CH_MOXIE_TASK = "Trouve ta Moxie dans l'onglet des monnaies et vérifie ton solde.",
	PROFACAD_CH_WEEKLY_TITLE = "Ta routine hebdomadaire",
	PROFACAD_CH_WEEKLY_BODY = "La plupart des PS viennent de sources hebdomadaires répétables. La base pour chaque métier :\n\n1. Quête hebdo du formateur — se débloque après la quête d'intro chez Captain Flaresworn (station de commandes, Bazar de Lune-d'argent). L'Enchantement demande d'abord compétence 25.\n2. Deux objets-trésors aléatoires dans les conteneurs du monde (+2 PS chacun).\n3. Un Traité thalassien (+1 PS) — fabriqué par Calligraphie ; lié au régiment, donc un reroll ou une commande t'en procure un.\n4. Semaine de la Foire de Sombrelune : +3 PS et +15 Moxie, chaque mois.\n\nUne semaine manquée ? Le système de rattrapage rend lentement les PS manqués — après avoir fini les hebdos en cours.",
	PROFACAD_CH_WEEKLY_TASK = "Prends la quête d'intro chez Captain Flaresworn et fais ta première hebdo de formateur.",
	PROFACAD_CH_ENCHANTING_TITLE = "Guide de départ Enchantement",
	PROFACAD_CH_ENCHANTING_BODY = "L'Enchantement fait bande à part : tu gagnes la plupart de tes PS hebdos en désenchantant de l'équipement. Chaque semaine, les 5 premières Essences arcaniques tourbillonnantes donnent +1 PS chacune, puis un Éclat de mana débordant donne +4 — soit +9 PS par semaine juste en broyant du butin. L'Enchantement n'a pas de commandes de mécènes.\n\nBuild de départ (consensus communautaire) : Spellbound Shatterer d'abord (son buff Shatter Essence booste tes stats d'artisanat), puis Elevating Equipment — racine jusqu'à ~30, puis la branche Arme/Anneau/Torse (les enchantements les plus demandés). Disenchanting Delegate est un solide troisième choix pour l'autosuffisance en matériaux.\n\nLivres de PS bonus : Cour de Lune-d'argent renommée 6, et le vendeur de l'événement Abundance (Chel the Chip) vend aussi un livre d'Enchantement.",
	PROFACAD_CH_ENCHANTING_TASK = "Désenchante de l'équipement jusqu'à avoir tes 5 Essences + Éclat de mana de la semaine (+9 PS).",
	PROFACAD_CH_ALCHEMY_TITLE = "Guide de départ Alchimie",
	PROFACAD_CH_ALCHEMY_BODY = "Les arbres d'Alchimie se débloquent à compétence 25/50/60/75 : Potion Prowess (potions, partage Lumière/Vide), Fluent in Flasks (flacons, fioles et un chaudron de groupe), Transmutation Authority et Alchemical Mastery.\n\nBuild de départ : mets tes 20-30 premiers PS dans Fluent in Flasks ou Potion Prowess — ce sont les recettes que les raiders et joueurs M+ achètent toute l'année. Transmutations et Mastery viendront plus tard.\n\nLe premier jour peut être explosif : premières fabrications plus trésors uniques valent environ 40-50 PS. Les commandes de mécènes (tableau de commandes) sont ton moteur hebdo de PS — fais-les chaque semaine. Le livre de PS de renommée est chez The Singularity renommée 9.",
	PROFACAD_CH_ALCHEMY_TASK = "Fais tes commandes de mécènes disponibles cette semaine (tableau de commandes).",
	PROFACAD_CH_TAILORING_TITLE = "Guide de départ Couture",
	PROFACAD_CH_TAILORING_BODY = "Les couturiers sont la seule source d'armures en tissu fabriquées — et des rouleaux (Arcanoweave et Sunfire Silk) qui alimentent sacs, équipement embelli et spellthreads. Ces rouleaux sont derrière un cooldown quotidien que seuls les couturiers spécialisés débloquent : raison de plus pour se spécialiser réfléchi.\n\nBuild de départ : mets tes ~30 premiers points dans la racine Nimble Needlework (compétence et stats pour armure ET rouleaux), puis choisis ton axe. Armure : Sin'dorei Finery — choisis UN groupe d'emplacements (p. ex. robes/pantalons/capes) et maximise-le avant d'en commencer un autre. Rouleaux/or : Sunfire Silk Weaving ou Arcanoweaving plus le nœud Expertise (plus de rouleaux, cooldown plus court).\n\nFiber Arts et Fabric Specialist améliorent chaque craft (et tes drops de tissu dans certaines zones) — parfait pour les points restants.",
	PROFACAD_CH_TAILORING_TASK = "Débloque un rouleau via Nimble Needlework et lance ton cooldown de rouleau aujourd'hui.",
	PROFACAD_CH_LEATHERWORKING_TITLE = "Guide de départ Travail du cuir",
	PROFACAD_CH_LEATHERWORKING_BODY = "Les travailleurs du cuir sont la seule source d'armures en cuir ET en mailles fabriquées — deux arbres séparés, choisis donc d'abord un type d'armure. Learned Leatherworker est l'arbre des fondamentaux et réduit même le coût en Concentration par craft.\n\nBuild de départ : Learned Leatherworker d'abord, puis Lasting Leather (cuir) OU Safeguarding Scales (mailles), en maximisant un sous-nœud d'emplacement à la fois. Flawless Fortes vient ensuite : outils de métier d'un côté, consommables (kits d'armure, tambours) de l'autre — ils se vendent régulièrement.",
	PROFACAD_CH_LEATHERWORKING_TASK = "Choisis cuir ou mailles et maximise ton premier sous-nœud d'emplacement.",
	PROFACAD_CH_BLACKSMITHING_TITLE = "Guide de départ Forge",
	PROFACAD_CH_BLACKSMITHING_BODY = "Les forgerons sont la seule source d'armures en plaques fabriquées, plus pierres à armes, pierres à outils et alliages. The Old Ways est ton arbre des fondamentaux (Ingenuity, Multicraft, Resourcefulness pour TOUS les crafts) — alimente-le quoi que tu choisisses.\n\nPuis choisis un axe : Armorsmithing (par groupe d'emplacements) ou Weaponsmithing (par type d'arme) — maximise UN sous-nœud entièrement avant d'en commencer un autre. Craftsmithing fabrique l'équipement de métier de six autres professions. Alliages et pierres se vendent bien sans commandes.",
	PROFACAD_CH_BLACKSMITHING_TASK = "Choisis ton arbre principal (Armorsmithing ou Weaponsmithing) et maximise d'abord un sous-nœud.",
	PROFACAD_CH_ENGINEERING_TITLE = "Guide de départ Ingénierie",
	PROFACAD_CH_ENGINEERING_BODY = "Les ingénieurs sont la seule source de fusils et fabriquent lunettes (réservées aux ingénieurs), bracelets et bottes — plus gadgets et viseurs. Recycling est l'arbre des fondamentaux : compétence sur TOUS les crafts, et il te rend des matériaux pendant le travail.\n\nAprès Recycling : choisis un arbre et maximise d'abord un nœud. Attention : dans Bits and Bots les noms trompent — Bits = composants/rouages (viseurs), Bots = composants optionnels et gadgets. Viseurs, accessoires de bottes et gadgets se vendent bien à l'hôtel des ventes.",
	PROFACAD_CH_ENGINEERING_TASK = "Mets tes premiers points dans Recycling, puis choisis ton arbre principal.",
	PROFACAD_CH_INSCRIPTION_TITLE = "Guide de départ Calligraphie",
	PROFACAD_CH_INSCRIPTION_BODY = "Les calligraphes fabriquent bâtons, arcs, mains gauches, missives (stats sur l'équipement fabriqué), runes Vantus et cartes de Sombrelune. Atout unique : maximiser le nœud central Calm Hands débloque la Thalassian Treatise hebdomadaire — +2 PS par semaine, seul métier à l'avoir.\n\nDonc : Calm Hands d'abord, toujours. Ensuite Blueprints (équipement), Perfected Products (consommables) ou Darkmoon Curiosity (cartes, par type). Runes Vantus, missives et encres se vendent régulièrement.",
	PROFACAD_CH_INSCRIPTION_TASK = "Vise le nœud central Calm Hands au maximum (Treatise hebdo = +2 PS/semaine).",
	PROFACAD_CH_JEWELCRAFTING_TITLE = "Guide de départ Joaillerie",
	PROFACAD_CH_JEWELCRAFTING_BODY = "Les joailliers sont la seule source d'anneaux et de colliers fabriqués — tout le monde en a besoin. La prospection transforme le minerai en gemmes ; le concassage transforme les gemmes en trop en Gemdust. Astuce : ne dépense jamais de Concentration en prospection ou concassage.\n\nCommence par Thoughtful Throughput (fondamentaux), puis deux raccourcis : seul le nœud central Glamorous Gems est nécessaire pour tailler les Eversong Diamonds en qualité max, et Proficient Processor (prospection/concassage) est bon marché à compléter. Gemmes taillées et composants comme Sunglass Vial se vendent bien.",
	PROFACAD_CH_JEWELCRAFTING_TASK = "Débloque le nœud central Glamorous Gems et taille ta première gemme de qualité.",
	PROFACAD_CH_HERBALISM_TITLE = "Guide de départ Herboristerie",
	PROFACAD_CH_HERBALISM_BODY = "Chaque herbe pousse dans chaque zone — pas de stress de zone. Le grand déblocage : récolter en monture. Mets tes ~40 premiers points dans la racine Botany pour ça (les druides sautent cette étape — ils récoltent déjà montés — et vont droit à Bountiful Harvests).\n\nEnsuite ~40 dans Bountiful Harvests (plus d'herbes par nœud, plus de compétence = plus de qualité max), puis les bonus par herbe sur ce qui se vend le mieux. Midnight Overload ajoute un cooldown de 30 minutes sur les herbes infusées qui génère des motes.",
	PROFACAD_CH_HERBALISM_TASK = "Débloque la récolte en monture via la racine Botany (à sauter en druide).",
	PROFACAD_CH_MINING_TITLE = "Guide de départ Minage",
	PROFACAD_CH_MINING_BODY = "Tous les minerais apparaissent dans toutes les zones. Premier objectif : ~40 points dans la racine Meticulous Mining pour miner en monture — LE confort de Midnight. Puis ~50 dans la racine Plentiful Ores pour la compétence sur chaque minerai.\n\nEnsuite, remplis les nœuds par minerai (répartis également, sauf si un minerai vaut bien plus) ; un minerai au max augmente ses drops de Dazzling Thorium. Over-LODE (cooldown 30 minutes) surcharge les gisements infusés pour des motes. Refulgent Copper est demandé en permanence.",
	PROFACAD_CH_MINING_TASK = "Débloque le minage en monture via la racine Meticulous Mining.",
	PROFACAD_CH_SKINNING_TITLE = "Guide de départ Dépeçage",
	PROFACAD_CH_SKINNING_BODY = "Les dépeceurs alimentent les travailleurs du cuir — et Midnight te donne des outils : les bêtes de valeur s'affichent sur la minicarte, les Diffuseurs tirent des motes des monstres, et les Majestic Lures (Talented Tracker) invoquent une bête de zone une fois par jour qui lâche des matériaux épiques.\n\nBuild de départ (farm) : quelques points dans la racine Thorough Tanning, puis maximise la branche cuir ou écailles, puis retour dans la racine. Ensuite Gainful Gathering : Careful Carving (Finesse, farm de masse) ou Trophy Taker (Perception, rares). Change d'outil en conséquence : Finesse pour le volume, Perception pour les rares.",
	PROFACAD_CH_SKINNING_TASK = "Maximise la branche cuir ou écailles dans Thorough Tanning et dépèce avec l'outil adapté.",
	TAB_DELVE_LOG = "Journal des plongées",
	DELVELOG_SUBTITLE = "Un journal par personnage de chaque plongée de Minuit terminée : palier, temps, morts, clé utilisée et le boss final. Suivi automatiquement — pas besoin de garder cet onglet ouvert.",
	DELVELOG_EMPTY = "Aucune plongée enregistrée pour l'instant. Termine une plongée de Minuit pour commencer le suivi.",
	DELVELOG_CLEAR = "Vider le journal",
	DELVELOG_CLEAR_CONFIRM = "Effacer tout le journal des plongées de ce personnage ? Cette action est irréversible.",
	DELVELOG_LBL_RUNS = "Plongées :",
	DELVELOG_LBL_BEST = "Meilleur :",
	DELVELOG_LBL_AVG = "Moy. :",
	DELVELOG_LBL_FASTEST = "Plus rapide :",
	DELVELOG_LBL_DEATHS = "Morts :",
	DELVELOG_LBL_KEY = "Clé",
	DELVELOG_TOTAL_TIME = "Temps total :",
	INFO_DRAWER_BODY_DELVELOG = "Le Journal des plongées enregistre chaque plongée de Minuit que tu termines sur ce personnage. Clique sur une plongée pour déplier ses dernières runs. Chaque run indique le palier, le temps, les morts, si tu as utilisé une Clé de coffre restaurée et le boss final. Le suivi tourne en arrière-plan ; cet onglet n'a pas besoin d'être ouvert.",
	TAB_WORLD = "Void & Rituals",
	WORLD_SUBTITLE = "Contenu de monde hebdomadaire de Midnight à Quel'Thalas. Un Site rituel est actif dans une zone et le Vide attaque une autre — les deux partagent le hub du Bazar, les Distinctions de terrain et la renommée.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals réunit les deux systèmes de monde tournants de Midnight. Sites rituels : perturbe le site actif (icône violette) à son obélisque. Assauts du Vide : nettoie les Frappes du Vide dans la zone active pour déclencher une Incursion du Vide. Les deux donnent des Distinctions de terrain, remplissent ta rangée de monde de la Grande Chambre forte et alimentent la renommée commune des Sites rituels. Les deux quêtes hebdo se prennent au hub du Bazar à Lune-d'argent.",
	TAB_REFERENCE = "Bases",
	REF_PANEL_INTRO = "Explications simples sur les systèmes de fin de partie. D'autres sujets arriveront ici.",
	REF_MORE_COMING = "D'autres guides bientôt (métiers, équipement, etc.).",
	INFO_DRAWER_BODY_REFERENCE = "Guides pour débutants : Dawncrests, où les dépenser et bonus de bataillon. D'autres sujets (métiers, etc.) suivront.",
	TAB_SMC = "Guide de la ville SMC",
	TAB_PROFESSIONS = "Métiers",
	TAB_GUIDE = "Guides de mise à niveau",
	TAB_MACROS = "Macro",
	TAB_CONSUMABLES = "Consommables",
	TAB_ACADEMY = "Académie de rôle",
	TAB_TOOLBOX = "Boîte à outils",
	-- Articles codex du patch 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns : Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Un portail dans le Voidstorm (Screaming Ridge) mène vers l'un des deux mondes du Vide en rotation : Naigtal le fongique ou Val le glacial. Chacun propose des expéditions mondiales, des rares, des événements de zone et un boss mondial (Nexus-Captain Leth'ir / Imperator Pertinax). L'hebdomadaire Showdown octroie une Riftstalker's Cache et compte pour la rangée World du Grand Coffre. La Heroic World Tier optionnelle augmente difficulté et récompenses — choix au portail. Départ : Riftblade Maella à Lune-d'argent.",
	CODEX_127_SPOREFALL_TITLE = "Raid Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Raid à un boss à Harandar : Rotmire, un géant fongique. Même palier Saison 1 avec des niveaux d'objet supérieurs (LFR 259 / Normal 272 / Héroïque 285 / Mythique 298) ; le Mythique est flexible de 15 à 25 joueurs. Récupérez un Delicious Sporesnack une fois par semaine, peu importe la difficulté — quatre au total achètent la monture Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runes (12.0.7)",
	CODEX_127_FOLIO_BODY = "Nouveau système de puissance sans emplacement d'équipement. Débloqué via la campagne du Sunstrider Omnium avec le magistère Umbric et le grand magistère Rommath à Quel'Danas. Chaque semaine, la quête 'Seeking Knowledge' donne un Mote of Omnial Inquiry pour ouvrir l'une des cinq rangées de runes ; les runes s'échangent librement hors combat.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 juin - 11 août)",
	CODEX_127_TIMEWAYS_BODY = "Marathon des Marcheurs du temps avec six donjons Dragonflight. Faites quatre donjons dans la semaine pour le buff Mastery de la semaine ; obtenez Mastery sur quatre semaines distinctes pour la monture Spawn of Vyranoth.",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "En cours de développement",
	TAB_BETA_TOOLTIP_BODY = "Cet onglet est en beta précoce — le contenu est incomplet, peut changer souvent et n'est pas prêt pour un usage complet.",
	TAB_ADDONS = "Modules complémentaires",
	SEARCH_CHAT_TAB_ACADEMY = "Onglet ouvert : Académie de rôle",
	ACADEMY_SUBTITLE = "Courte masterclass sur le tanking et la guérison en groupe : état d'esprit, cases à cocher de préparation et rampe douce vers les donjons. Pas un guide d'analyse.",
	ACADEMY_TRACK_TANK = "Piste de char",
	ACADEMY_TRACK_HEAL = "Piste de guérison",
	ACADEMY_LINK_MACROS = "Macro",
	ACADEMY_LINK_CONSUMABLES = "Consommables",
	ACADEMY_LINK_GUIDE = "Guides",
	ACADEMY_LINK_DELVES = "Gouffres",
	ACADEMY_LINK_CLASS = "Ma classe",
	ACADEMY_CLASS_FMT = "Connecté : %s - %s (ouvre Macros / Consommables / Guides depuis la barre latérale)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros ouvertes pour %s - %s. Regarde aussi Consommables pour flacons et pots.",
	ACADEMY_PREF_TITLE = "Checklist avant de partir (coche quand tu es prêt)",
	ACADEMY_PREF_HINT = "Les coches sont enregistrées dans tes paramètres. Ouvre l'onglet correspondant dans la barre latérale quand tu te prépares.",
	ACADEMY_PREF_TANK_INTERRUPT = "Macro d'interruption sur ma barre (onglet Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Un prêt défensif (onglet Guides -> Défensifs ou En groupes)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flacon / pot prêt (onglet Consommables)",
	ACADEMY_PREF_TANK_TAUNT = "Je connais ma clé de provocation (test factice une fois)",
	ACADEMY_PREF_HEAL_MACROS = "Survol de la souris / macros de guérison de focus (onglet Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Défensive personnelle sur la barre (Guides -> Défensives ou En groupes)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pot / flacon de mana (onglet Consommables)",
	ACADEMY_PREF_HEAL_PRACTICE = "J'ai pratiqué le survol de soins sur un ami une fois.",
	ACADEMY_TANK_INTRO_TITLE = "Esprit de tank",
	ACADEMY_TANK_INTRO_BODY = "Ton job : donner le rythme et capter l'aggro — pas topper le compteur de dégâts.\\n\\nUn pull régulier bat une rotation parfaite sur un groupe mort. Dis « pull dans 3 » à voix haute si ça aide.",
	ACADEMY_TANK_PULL_TITLE = "Pendant un pull (10 premières secondes)",
	ACADEMY_TANK_PULL_BODY = "1. Prends le pack (provoc/menace).\\n2. Tourne les ennemis loin du groupe quand tu peux.\\n3. Utilise une défensive si les dégâts montent — garde la deuxième pour « oh non ».\\n4. Interromps le sort qui fait le plus mal (souvent soin ou gros coup).\\n\\nTu n'as pas besoin de tout mettre en cooldown tout de suite.",
	ACADEMY_TANK_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_TANK_WIPE_BODY = "Un wipe, c'est des données, pas un verdict. Demande-toi : « Trop en avance ? » ou « J'ai gardé une défensive ? »\\n\\nRépare, mange, réessaie.",
	ACADEMY_TANK_DUNGEON_TITLE = "Ton premier donjon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Commence en normal avec des amis ou la guilde si tu peux. Pull doucement — deux petits packs valent mieux qu'une longue chaîne.\\n\\nSurveille le mana du soigneur ; pause entre les pulls. Demander un CC ou « pas de gros pull » est ok.",
	ACADEMY_TANK_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_TANK_RAID_BODY = "LFR est l'intro raid douce : indulgent, beaucoup de soigneurs. Focus sur le timing des provocs boss et rester au bon endroit.\\n\\nLe tank mythique raid n'est pas l'étape suivante — d'abord le confort en héroïque/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Chat de groupe",
	ACADEMY_CHAT_HINT = "Clique une ligne ou l'icône copier, puis Ctrl+C pour coller dans le chat de groupe.",
	ACADEMY_CHAT_COPY_TIP = "Sélectionne cette ligne (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\\\"Tank en apprentissage — allez doucement svp.\\\"\\n\\\"Pull dans 3...\\\"\\n\\\"Pause mana.\\\"\\n\\\"Inter sur [nom du sort] — je le prends après.\\\"\\n\\\"Encore un essai — je connais ce pull.\\\"",
	ACADEMY_TANK_LADDER_TITLE = "Échelle d'anxiété (ordre conseillé)",
	ACADEMY_TANK_LADDER_BODY = "1. Élites monde ouvert avec un ami\\n2. Gouffres (petite instance — onglet Gouffres)\\n3. Donjon normal avec des gens de confiance\\n4. Héroïque / LFR quand tu es à l'aise\\n\\nSaute une étape jusqu'à que ce soit ennuyeux, pas effrayant.",
	ACADEMY_TANK_BOTH_TITLE = "Tu apprends aussi à soigner ?",
	ACADEMY_TANK_BOTH_BODY = "Super — mais choisis un rôle principal en donjon un moment. Entraîne l'autre en gouffres ou en monde ouvert.\\n\\nTank + heal dans le même M+ pug double le stress ; maîtriser un rôle d'abord donne confiance pour le second.",
	ACADEMY_HEAL_INTRO_TITLE = "État d'esprit soigneur",
	ACADEMY_HEAL_INTRO_BODY = "Tu n'es pas responsable de tout le monde à 100 % PV tout le temps.\\n\\nTon job : triage — garder le tank en vie, sauver celui qui va mourir, puis le reste. Un peu de dégâts est normal — le overheal paniqué vide le mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (qui en premier ?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Toi (si tu meurs — un soigneur mort ne soigne personne)\\n2. Tank (si le pack est encore sur lui)\\n3. Quiconque sous ~40 % ou avec un debuff mortel\\n4. Le reste avec des soins efficaces\\n\\nGros soin après gros dégâts ; petits soins entre les événements.",
	ACADEMY_HEAL_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_HEAL_WIPE_BODY = "« Aurais-je pu sauver le tank ? » est la bonne question — pas « pourquoi le DPS est resté dans le feu ? »\\n\\nSi le mana était vide, utilise des sorts plus efficaces la prochaine fois. Un wipe ne veut pas dire que tu ne peux pas soigner.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Ton premier donjon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Dis au groupe que tu apprends. Reste à portée du tank ; laisse le DPS prendre une égratignure avant de brûler le mana.\\n\\nEntre les pulls : boire, buff, respirer. « oom, 5 sec » est ok.",
	ACADEMY_HEAL_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_HEAL_RAID_BODY = "LFR : les dégâts à l’échelle du raid sont prévisibles après un seul nettoyage. Apprenez le chronomètre de combat, pas les barres de chaque joueur.\\n\\nLes soins de raid utilisent le même triage : les fenêtres de temps de recharge des tanks et des raids en premier.",
	ACADEMY_HEAL_CHAT_TITLE = "Discussion de groupe",
	ACADEMY_HEAL_CHAT_BODY = "\\\"Apprentissage du guérisseur - J'appellerai le mana faible.\\\"\\n\\\"Le tank est prioritaire - criez si tu avez besoin de respirer.\\\"\\n\\\"Gros soin sur tu - surveillez ton santé.\\\"\\n\\\"Oom 5 secondes entre les tirages.\\\"\\n\\\"C'était de ma faute - j'en garderai plus pour le tank au prochain tirage.\\\"",
	ACADEMY_HEAL_LADDER_TITLE = "Échelle d'anxiété (ordre recommandé)",
	ACADEMY_HEAL_LADDER_BODY = "1. Soigne un ami en monde ouvert\\n2. Gouffres en petit groupe\\n3. Donjon normal avec des amis patients\\n4. Raid LFR / héroïque quand tu es prêt\\n\\nLes gouffres sont l'étape la plus douce vers le contenu instancié.",
	ACADEMY_HEAL_BOTH_TITLE = "Tu apprends aussi le tank ?",
	ACADEMY_HEAL_BOTH_BODY = "Utilise la piste Tank pour la file donjon ; continue de soigner en gouffres jusqu'à ce que le tank te semble familier.\\n\\nDeux rôles en une semaine en pug, c'est beaucoup — un rôle « principal » réduit la peur.",
	INFO_DRAWER_BODY_ACADEMY = "Académie des rôles : pistes tank/soigneur, checklist, notes donjon vs raid et lignes de chat de groupe. Les guides de niveau ajoutent l'onglet En groupe par rôle. Barre latérale : macros, consommables, guides et gouffres.",
	TAB_GUIDE_SUB_GUIDE = "Guide",
	TAB_GUIDE_SUB_LAYOUT = "Mise en page",
	TAB_LEVELING_SUB_LAYOUT = "Mise en page",
	MACROS_TYPE_INTERRUPT = "Interrompre",
