	GUIDE_STATS_SHAMAN_RESTO = "|cffffcc00Intellect|r > |cffffcc00Polyvalence|r > |cffffcc00Critique|r",
	GUIDE_STATS_WARLOCK_DEMONOLOGY = "|cffffcc00Intellect|r > |cffffcc00Hâte|r > |cffffcc00Maîtrise|r",
	GUIDE_STATS_WARLOCK_DESTRUCTION = "|cffffcc00Intellect|r > |cffffcc00Hâte|r > |cffffcc00Critique|r",
	GUIDE_STATS_WARRIOR_ARMS = "|cffffcc00Force|r > |cffffcc00Critique|r > |cffffcc00Haste|r",
	GUIDE_STATS_WARRIOR_PROTECTION = "|cffffcc00Force|r > |cffffcc00Hâte|r > |cffffcc00Polyvalence|r",
	GUIDE_PANEL_MISSING = "Guide — ns.panels.guide manquant (l'interface utilisateur n'est pas encore prête ?).",
}

local function shouldCopyFromEnUS(key)
	if type(key) ~= "string" then
		return false
	end
	if key:match("^GUIDE_ADVISOR_") then
		return false
	end
	if key:match("^GUIDE_TIP_") then
		return false
	end
	if key:match("^GUIDE_GEAR_(MAGE|DK|DH|PRIEST|PALADIN|ROGUE|SHAMAN|WARRIOR|MONK|HUNTER|DRUID|WARLOCK|EVOKER)_") then
		return false
	end
	return true
end

local pack = {}
local en = ns._mhLocales.enUS
if type(en) == "table" then
	for key, value in pairs(en) do
		if shouldCopyFromEnUS(key) and type(value) == "string" then
			pack[key] = OVERRIDES[key] or value
		end
	end
end
for key, value in pairs(OVERRIDES) do
	pack[key] = value
end

ns._mhLocales.frFR = pack
